(()=>{const toggle=document.querySelector('#deployment-search-toggle'),panel=document.querySelector('#deployment-search-panel'),input=document.querySelector('#deployment-search'),more=document.querySelector('#deployment-more'),rows=[...document.querySelectorAll('.deployment-update')];let expanded=false;function render(){const query=input.value.trim().toLowerCase(),matching=rows.filter(r=>r.textContent.toLowerCase().includes(query));rows.forEach(r=>r.hidden=!matching.includes(r)||(!expanded&&!query&&matching.indexOf(r)>=6));more.hidden=!!query||expanded||matching.length<=6;document.querySelector('#deployment-results').textContent=query?`${matching.length} ${matching.length===1?'update':'updates'} found`:''}toggle.addEventListener('click',()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));toggle.setAttribute('aria-label',panel.hidden?'Open search':'Close search');if(!panel.hidden)input.focus();else{input.value='';render()}});input.addEventListener('input',render);input.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open search');input.value='';render();toggle.focus()}});more.addEventListener('click',()=>{expanded=true;render()});render()})();
